mapper.select:
SELECT a.num, a.title, a.content, a.writer, a.viewcnt, a.image_filename AS imageFilename, a.download_filename AS downloadFilename, m.name AS writerName, m.profile AS profile
FROM article a LEFT JOIN member m ON a.writer = m.id
WHERE a.num = #{num}

mapper.update:
update article
set title=#{title},
content=#{content}

	, image_filename=#{imageFilename}


	, download_filename=#{downloadFilename}

where num=#{num}
